def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opps = []
    prev_bids = []
    opp_requirements = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append(opp)
            opp_requirements.append(opp.get('water_requirement', WATER_REQ))
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(float(prev['bid']))

    if not alive_opps:
        if hp <= 2 or no_water_days >= 2:
            return min(budget, 45.0)
        return min(budget, 18.0)

    total_req = WATER_REQ
    for req in opp_requirements:
        total_req += req

    scarcity = total_req / max(supply, 1.0)
    high_supply = supply >= 22.0
    low_supply = supply <= 17.0

    highest_prev = max(prev_bids) if prev_bids else 0.0
    lowest_prev = min(prev_bids) if prev_bids else 0.0

    urgent = hp <= 2 or no_water_days >= 2
    pressured = hp <= 4 or no_water_days >= 1

    bid = 0.0

    if urgent:
        if low_supply:
            bid = max(110.0, highest_prev + 2.0)
        else:
            bid = max(92.0, min(108.0, highest_prev * 0.92 + 4.0))
    elif pressured:
        if high_supply:
            bid = max(58.0, min(86.0, lowest_prev + 2.5 if prev_bids else 68.0))
        elif low_supply:
            bid = max(88.0, min(108.0, highest_prev + 1.0 if prev_bids else 95.0))
        else:
            bid = max(72.0, min(94.0, 0.55 * highest_prev + 28.0 if prev_bids else 80.0))
    else:
        if high_supply:
            bid = max(32.0, min(68.0, lowest_prev - 6.0 if prev_bids else 45.0))
        elif low_supply:
            bid = max(74.0, min(92.0, 0.8 * highest_prev if prev_bids else 82.0))
        else:
            bid = max(52.0, min(78.0, 0.6 * highest_prev + 6.0 if prev_bids else 62.0))

    if scarcity > 3.0:
        bid += 8.0
    elif scarcity < 2.4:
        bid -= 6.0

    if day >= 8:
        if hp >= 6 and budget < DAILY_SALARY * 3:
            bid -= 6.0
        elif hp <= 4:
            bid += 6.0

    reserve = 0.0
    if day <= 7:
        reserve = DAILY_SALARY * 1.0
    elif day <= 9:
        reserve = DAILY_SALARY * 0.5

    affordable = max(0.0, budget - reserve)
    if urgent:
        affordable = budget

    bid = max(0.0, bid)
    bid = min(budget, bid)
    if affordable > 0.0:
        bid = min(bid, affordable) if not urgent else min(bid, budget)

    if bid < 1.0 and budget >= 1.0:
        bid = 1.0

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    my_hp = float(my_status.get('hp', 0.0))
    my_budget = float(my_status.get('budget', 0.0))
    my_no_water_days = int(my_status.get('no_water_days', 0))

    alive_opps = []
    for oid, o in opponents_status.items():
        if o.get('alive', False):
            alive_opps.append(o)

    if not alive_opps:
        return min(my_budget, DAILY_SALARY * 0.4)

    # Extract yesterday bids and survival pressure.
    prev_bids = []
    for o in alive_opps:
        prev = o.get('previous_trace', {}) or {}
        b = prev.get('bid', None)
        if b is not None:
            try:
                prev_bids.append(float(b))
            except Exception:
                pass

    highest_prev_bid = max(prev_bids) if prev_bids else 0.0

    # Estimate how many water units are likely available.
    # If supply is low, we need to outbid more to secure water.
    # supply is total water; per unit demand is WATER_REQ.
    est_units = max(1, int(supply / float(WATER_REQ)))

    # Base bid: target a fraction of DAILY_SALARY depending on supply/urgency.
    # Urgency increases with low hp or consecutive no-water days.
    urgency = 0.0
    if my_hp <= 2.0:
        urgency += 1.0
    elif my_hp <= 4.0:
        urgency += 0.6
    if my_no_water_days >= 2:
        urgency += 0.7
    elif my_no_water_days == 1:
        urgency += 0.3

    # Supply pressure: fewer units => higher bid.
    # With supply 15-25 and WATER_REQ=9 => units typically 1-2.
    if est_units <= 1:
        supply_pressure = 1.0
    else:
        supply_pressure = 0.6

    # Use yesterday's highest bid as a guide: if others already paid huge amounts, we may need to match partially.
    # But avoid full commitment; aim to beat the underbidders while not matching the top bidder exactly.
    match_factor = 0.55
    if highest_prev_bid >= DAILY_SALARY * 1.0:
        # Others likely bidding aggressively to survive.
        match_factor = 0.65

    # Compute target bid.
    # If supply is low and urgency is high, bid close to salary; else moderate.
    target = DAILY_SALARY * (0.35 + 0.35 * supply_pressure + 0.25 * urgency)

    # If yesterday had very high bids, raise target to compete.
    if highest_prev_bid > 0:
        target = max(target, highest_prev_bid * match_factor)

    # Clamp to budget and keep within reasonable range.
    # Also ensure we don't bid zero when we need water.
    if my_hp <= 2.0 or my_no_water_days >= 2:
        floor_bid = DAILY_SALARY * 0.75
    elif my_hp <= 4.0 or my_no_water_days >= 1:
        floor_bid = DAILY_SALARY * 0.55
    else:
        floor_bid = DAILY_SALARY * 0.35

    target = max(target, floor_bid)

    # Final cap
    bid = min(my_budget, target)

    # If budget is tiny, still bid something proportional but nonzero.
    if bid <= 0.0:
        bid = min(my_budget, DAILY_SALARY * 0.1)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    alive_opps = [o for o in opponents_status.values() if o['alive']]
    # determine aggressive threshold from yesterday
    high_bid = False
    for opp in alive_opps:
        prev = opp.get('previous_trace', {})
        if prev and 'bid' in prev:
            if prev['bid'] >= 80:
                high_bid = True
    # base bid: depend on supply
    if supply >= 22:
        base = DAILY_SALARY * 0.4
    elif supply >= 18:
        base = DAILY_SALARY * 0.6
    else:
        base = DAILY_SALARY * 0.85
    # adjust for HP and competition
    if hp <= 2:
        bid = min(budget, DAILY_SALARY * 1.0)
    elif high_bid:
        bid = min(budget, max(base, 100))
    else:
        bid = min(budget, base)
    # ensure at least something
    bid = max(bid, 0.1)
    return min(bid, budget) if budget else bid
